package warehouse.health;

import static readcode.Assert.*;

public class HealthTest {

    private HealthRegistry registry;

    public void setUp() {
        registry = new HealthRegistry();
    }

    public void testAllUp() {
        registry.register("database", true, Checks.ping(() -> true))
                .register("label-printer", false, Checks.ping(() -> true));
        assertEquals(Status.UP, registry.run().status());
    }

    public void testOptionalDownAloneIsDegraded() {
        registry.register("database", true, Checks.ping(() -> true))
                .register("label-printer", false, Checks.ping(() -> false));
        HealthReport report = registry.run();
        assertEquals(Status.DEGRADED, report.status());
        assertTrue(report.isReady(), "a degraded service is still ready");
    }

    public void testCriticalDownIsDown() {
        registry.register("label-printer", false, Checks.ping(() -> true))
                .register("database", true, Checks.ping(() -> false));
        assertEquals(Status.DOWN, registry.run().status());
    }

    public void testCriticalDownBeforeFailingOptionalStaysDown() {
        registry.register("database", true, Checks.ping(() -> false))
                .register("label-printer", false, Checks.ping(() -> false));
        HealthReport report = registry.run();
        System.out.println("components: " + report.components() + " -> " + report.status());
        assertEquals(Status.DOWN, report.status(), "database is critical and down, so the service is down");
    }

    public void testThrowingCheckCountsAsDown() {
        registry.register("database", true, () -> {
            throw new IllegalStateException("connection refused");
        });
        HealthReport report = registry.run();
        assertEquals(Status.DOWN, report.components().get("database"));
        assertEquals(Status.DOWN, report.status());
    }

    public void testQueueDepthThresholds() {
        registry.register("inbound-queue", false, Checks.queueDepth(() -> 150, 100, 500));
        assertEquals(Status.DEGRADED, registry.run().status());
    }

    public void testEndpointReturns503WhenCriticalDependencyIsDown() {
        registry.register("database", true, Checks.ping(() -> false))
                .register("inbound-queue", false, Checks.queueDepth(() -> 900, 100, 500));
        HealthEndpoint.Response response = new HealthEndpoint(registry).readiness();
        assertEquals(503, response.code(), "load balancer must stop routing to this instance");
    }

    public void testEndpointReturns200WhenDegraded() {
        registry.register("database", true, Checks.ping(() -> true))
                .register("inbound-queue", false, Checks.queueDepth(() -> 900, 100, 500));
        HealthEndpoint.Response response = new HealthEndpoint(registry).readiness();
        assertEquals(200, response.code());
        assertTrue(response.body().contains("\"status\":\"DEGRADED\""), response.body());
    }
}
